package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class TickMetronomeTest
{
	@Test
	public void buildsValidWavHeaderAndPcm()
	{
		byte[] wav = TickMetronome.buildSoftTickWav();
		assertTrue(wav.length > 44);
		assertEquals('R', wav[0]);
		assertEquals('I', wav[1]);
		assertEquals('F', wav[2]);
		assertEquals('F', wav[3]);
		assertEquals('W', wav[8]);
		assertEquals('A', wav[9]);
		assertEquals('V', wav[10]);
		assertEquals('E', wav[11]);
	}
}

package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Before;
import org.junit.Test;

public class AttackCycleTrackerTest
{
	private AttackCycleTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new AttackCycleTracker();
	}

	@Test
	public void acquiresFourTickCadenceFromMetadata()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.onCredibleAttack(10);

		assertEquals(4, tracker.getCandidateAttackSpeedTicks());
		assertEquals(14, tracker.getNextReadyTick());
		assertEquals(CycleConfidence.HIGH, tracker.getConfidence());
		assertTrue(tracker.isReadyAt(14));
		assertFalse(tracker.isReadyAt(13));
	}

	@Test
	public void calculatesCorrectNextReadyTick()
	{
		tracker.setWeaponSpeedFromMetadata(5);
		tracker.onCredibleAttack(100);
		assertEquals(105, tracker.getNextReadyTick());
		assertEquals(3, tracker.ticksUntilReady(102));
		assertEquals(0, tracker.ticksUntilReady(105));
	}

	@Test
	public void reportsZeroDeltaForOnTimeAttack()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.onCredibleAttack(0);
		CycleFeedback feedback = tracker.onCredibleAttack(4);

		assertNotNull(feedback);
		assertEquals(0, feedback.getDeltaTicks());
		assertTrue(feedback.getSummary().toLowerCase().contains("ready"));
	}

	@Test
	public void reportsPlusOneForLateAttack()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.onCredibleAttack(0);
		CycleFeedback feedback = tracker.onCredibleAttack(5);

		assertNotNull(feedback);
		assertEquals(1, feedback.getDeltaTicks());
		assertTrue(feedback.getSummary().contains("1"));
	}

	@Test
	public void rejectsImpossibleEarlyAttackAndReacquires()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.onCredibleAttack(0);
		CycleFeedback feedback = tracker.onCredibleAttack(2);

		assertNull(feedback);
		assertEquals(CycleConfidence.NONE, tracker.getConfidence());
		assertEquals(AttackCyclePhase.ACQUIRING, tracker.getPhase());
	}

	@Test
	public void resetsOnEquipmentChange()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.noteEquipmentFingerprint("1:2:3");
		tracker.onCredibleAttack(10);
		assertEquals(CycleConfidence.HIGH, tracker.getConfidence());

		tracker.noteEquipmentFingerprint("9:2:3");
		assertEquals(CycleConfidence.NONE, tracker.getConfidence());
		assertEquals(-1, tracker.getLastCredibleAttackTick());
	}

	@Test
	public void downgradesOnTargetChange()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.noteTarget("goblin#1");
		tracker.onCredibleAttack(10);
		assertEquals(CycleConfidence.HIGH, tracker.getConfidence());

		tracker.noteTarget("cow#2");
		assertEquals(CycleConfidence.LOW, tracker.getConfidence());
	}

	@Test
	public void resetsOnInactivity()
	{
		tracker.setWeaponSpeedFromMetadata(4);
		tracker.onCredibleAttack(10);
		tracker.onTick(10 + AttackCycleTracker.INACTIVITY_TIMEOUT_TICKS);
		assertEquals(CycleConfidence.NONE, tracker.getConfidence());
		assertEquals(AttackCyclePhase.IDLE, tracker.getPhase());
	}

	@Test
	public void producesNoFeedbackAtLowConfidence()
	{
		// Observed cadence without weapon metadata needs multiple agreeing intervals
		// for high confidence. A single interval should not produce feedback yet.
		tracker.onCredibleAttack(0);
		CycleFeedback first = tracker.onCredibleAttack(4);
		assertNull(first);

		CycleFeedback second = tracker.onCredibleAttack(8);
		// Still low/none until enough agreeing intervals elevate confidence for feedback.
		// After two intervals of 4, consensus may reach LOW which does not allow feedback.
		assertNull(second);

		assertFalse(tracker.getConfidence().allowsFeedback());
	}

	@Test
	public void acquiresHighConfidenceFromRepeatedIntervals()
	{
		tracker.onCredibleAttack(0);
		tracker.onCredibleAttack(4);
		tracker.onCredibleAttack(8);
		tracker.onCredibleAttack(12);

		assertEquals(4, tracker.getCandidateAttackSpeedTicks());
		assertEquals(CycleConfidence.HIGH, tracker.getConfidence());

		CycleFeedback feedback = tracker.onCredibleAttack(16);
		assertNotNull(feedback);
		assertEquals(0, feedback.getDeltaTicks());
	}

	@Test
	public void unknownSpeedHidesReadiness()
	{
		tracker.onCredibleAttack(0);
		assertFalse(tracker.getConfidence().allowsReadiness());
		assertEquals(-1, tracker.ticksUntilReady(1));
		assertFalse(tracker.isReadyAt(4));
	}
}

package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import net.runelite.api.Prayer;
import net.runelite.api.gameval.SpriteID;
import org.junit.Test;

public class PrayerSpritesTest
{
	@Test
	public void mapsProtectFromMeleeSprite()
	{
		assertEquals(SpriteID.Prayeron.PROTECT_FROM_MELEE, PrayerSprites.spriteId(Prayer.PROTECT_FROM_MELEE));
	}

	@Test
	public void prefersActivatedPrayer()
	{
		long previous = 0L;
		long current = 1L << Prayer.PROTECT_FROM_MELEE.ordinal();
		Prayer picked = PrayerSprites.pickChangedPrayer(previous, current);
		assertEquals(Prayer.PROTECT_FROM_MELEE, picked);
	}

	@Test
	public void fallsBackToDeactivatedPrayer()
	{
		long previous = 1L << Prayer.PIETY.ordinal();
		long current = 0L;
		Prayer picked = PrayerSprites.pickChangedPrayer(previous, current);
		assertEquals(Prayer.PIETY, picked);
	}

	@Test
	public void noChangeReturnsNull()
	{
		assertNull(PrayerSprites.pickChangedPrayer(3L, 3L));
	}

	@Test
	public void shortLabelFitsSlot()
	{
		assertEquals("Protect", PrayerSprites.shortLabel(Prayer.PROTECT_FROM_MELEE));
		assertEquals("Protect", PrayerSprites.shortLabel(Prayer.PROTECT_FROM_MAGIC));
		assertEquals("Dampen", PrayerSprites.shortLabel(Prayer.RP_DAMPEN_MELEE));
		assertEquals("Piety", PrayerSprites.shortLabel(Prayer.PIETY));
		assertEquals("Ancient", PrayerSprites.shortLabel(Prayer.RP_ANCIENT_STRENGTH));
		assertNotNull(PrayerSprites.shortLabel(null));
	}

	@Test
	public void unknownPrayerUsesNeutralOrbSprite()
	{
		assertEquals(SpriteID.OrbIcon.PRAYER, PrayerSprites.spriteId(null));
		assertEquals(SpriteID.OrbIcon.PRAYER, PrayerSprites.GENERIC_SPRITE);
	}

	@Test
	public void matchFromTextResolvesPrayerNames()
	{
		assertEquals(Prayer.PIETY, PrayerSprites.matchFromText("activate piety"));
		assertEquals(Prayer.PROTECT_FROM_MELEE, PrayerSprites.matchFromText("protect from melee"));
		assertEquals(Prayer.PROTECT_ITEM, PrayerSprites.matchFromText("protect item"));
		assertNull(PrayerSprites.matchFromText("shark"));
	}
}

package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

public class TickFlowStateTest
{
	private TickFlowState state;

	@Before
	public void setUp()
	{
		state = new TickFlowState();
		state.setTimelineLength(5);
	}

	@Test
	public void rollingHistoryStaysBounded()
	{
		for (int i = 0; i < 30; i++)
		{
			state.beginNextTick("1,1,0", null, 0L, -1, "1:0:0", 4);
			state.recordAction(new TickAction(ActionType.MOVE, ActionSource.POSITION, "Move", 90, 0));
		}

		TickFlowState.Snapshot snap = state.snapshot();
		assertTrue(snap.getHistory().size() <= TickFlowState.MAX_HISTORY);
		assertTrue(snap.getHistory().size() <= Math.max(5, TickFlowState.MAX_TIMELINE));
	}

	@Test
	public void primaryActionPriorityIsDeterministic()
	{
		TickAction move = new TickAction(ActionType.MOVE, ActionSource.MENU, "Move", 90, 0);
		TickAction pray = new TickAction(ActionType.PRAYER, ActionSource.PRAYER_STATE, "Pray", 95, 1);
		TickAction attack = new TickAction(ActionType.ATTACK, ActionSource.MENU, "Attack", 85, 2);
		TickAction item = new TickAction(ActionType.CONSUMABLE, ActionSource.MENU, "Item", 70, 3);

		TickAction primary = TickFlowState.selectPrimary(Arrays.asList(move, pray, attack, item));
		assertEquals(ActionType.ATTACK, primary.getType());

		TickAction withoutAttack = TickFlowState.selectPrimary(Arrays.asList(move, pray, item));
		assertEquals(ActionType.CONSUMABLE, withoutAttack.getType());
	}

	@Test
	public void secondaryActionsArePreserved()
	{
		state.beginNextTick("1,1,0", "npc#1", 0L, -1, "1:0:0", 4);
		state.recordAction(new TickAction(ActionType.ATTACK, ActionSource.MENU, "Attack", 85, 0));
		state.recordAction(new TickAction(ActionType.MOVE, ActionSource.MENU, "Move", 80, 1));
		state.finalizeCurrentTick();

		List<TickRecord> history = state.snapshot().getHistory();
		assertEquals(1, history.size());
		TickRecord record = history.get(0);
		assertEquals(ActionType.ATTACK, record.getPrimaryAction().getType());
		assertEquals(1, record.getSecondaryActions().size());
		assertEquals(ActionType.MOVE, record.getSecondaryActions().get(0).getType());
	}

	@Test
	public void emptyTicksAreRepresentedNeutrally()
	{
		state.beginNextTick("1,1,0", null, 0L, -1, "1:0:0", -1);
		state.finalizeCurrentTick();

		TickRecord record = state.snapshot().getHistory().get(0);
		assertEquals(ActionType.EMPTY, record.getPrimaryAction().getType());
		assertEquals("Empty", record.getPrimaryAction().getLabel());
		assertTrue(record.getSecondaryActions().isEmpty());
	}

	@Test
	public void resetClearsStaleCombatTiming()
	{
		state.beginNextTick("1,1,0", "npc#1", 0L, -1, "1:0:0", 4);
		state.recordAction(new TickAction(ActionType.ATTACK, ActionSource.MENU, "Attack", 85, 0));
		state.beginNextTick("1,1,0", "npc#1", 0L, -1, "1:0:0", 4);
		assertTrue(state.getLocalTickIndex() >= 0);
		assertNotNull(state.snapshot().getCurrentTick());

		state.reset("test");
		assertEquals(-1, state.getLocalTickIndex());
		assertEquals(0, state.snapshot().getHistory().size());
		assertNull(state.snapshot().getCurrentTick());
		assertEquals(CycleConfidence.NONE, state.getAttackCycleTracker().getConfidence());
		assertEquals("test", state.getLastResetReason());
		assertFalse(state.isInCombat());
	}

	@Test
	public void movementFromTileChangeIsRecorded()
	{
		state.beginNextTick("10,10,0", null, 0L, -1, "1:0:0", 4);
		state.beginNextTick("11,10,0", null, 0L, -1, "1:0:0", 4);

		TickRecord current = state.snapshot().getCurrentTick();
		assertNotNull(current);
		assertEquals(ActionType.MOVE, current.getPrimaryAction().getType());
	}

	@Test
	public void prayerMaskChangeIsRecorded()
	{
		state.beginNextTick("10,10,0", null, 0L, -1, "1:0:0", 4);
		state.beginNextTick("10,10,0", null, 1L, -1, "1:0:0", 4);

		TickRecord current = state.snapshot().getCurrentTick();
		assertNotNull(current);
		assertEquals(ActionType.PRAYER, current.getPrimaryAction().getType());
	}

	@Test
	public void timelineLengthIsClamped()
	{
		assertEquals(5, TickFlowState.clampTimeline(1));
		assertEquals(8, TickFlowState.clampTimeline(99));
		assertEquals(6, TickFlowState.clampTimeline(6));
	}
}

package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import org.junit.Test;

public class TickFlowIconsTest
{
	@Test
	public void crispFitPreservesAspectAndDoesNotUpscale()
	{
		BufferedImage source = new BufferedImage(30, 20, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fitted = TickFlowIcons.crispFit(source, 24);
		assertEquals(24, fitted.getWidth());
		assertEquals(16, fitted.getHeight());
	}

	@Test
	public void crispFitKeepsNativeWhenAlreadySmall()
	{
		BufferedImage source = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fitted = TickFlowIcons.crispFit(source, 24);
		assertEquals(16, fitted.getWidth());
		assertEquals(16, fitted.getHeight());
	}

	@Test
	public void crispFitSmallBadgeStaysSquareWhenSourceIsSquare()
	{
		BufferedImage source = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		BufferedImage fitted = TickFlowIcons.crispFit(source, 12);
		assertEquals(12, fitted.getWidth());
		assertEquals(12, fitted.getHeight());
		assertTrue(fitted.getWidth() == fitted.getHeight());
	}
}

package com.tickflow;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.MenuAction;
import org.junit.Before;
import org.junit.Test;

public class ActionClassifierTest
{
	private ActionClassifier classifier;

	@Before
	public void setUp()
	{
		classifier = new ActionClassifier();
	}

	@Test
	public void classifiesWalkAsMove()
	{
		TickAction action = classifier.classifyMenu(MenuAction.WALK, "Walk here", "", 0);
		assertNotNull(action);
		assertEquals(ActionType.MOVE, action.getType());
	}

	@Test
	public void classifiesNpcAttackOption()
	{
		TickAction action = classifier.classifyMenu(MenuAction.NPC_FIRST_OPTION, "Attack", "Goblin", 0);
		assertNotNull(action);
		assertEquals(ActionType.ATTACK, action.getType());
	}

	@Test
	public void classifiesEatAsItem()
	{
		TickAction action = classifier.classifyMenu(MenuAction.CC_OP, "Eat", "Shark", 0);
		assertNotNull(action);
		assertEquals(ActionType.CONSUMABLE, action.getType());
	}

	@Test
	public void ignoresCancelAndRuneLiteMenus()
	{
		assertNull(classifier.classifyMenu(MenuAction.CANCEL, "Cancel", "", 0));
		assertNull(classifier.classifyMenu(MenuAction.RUNELITE_OVERLAY_CONFIG, "Configure", "TickFlow", 0));
	}

	@Test
	public void normalizesTagsInOptionText()
	{
		assertEquals("attack", ActionClassifier.normalize("<col=ff9040>Attack</col>"));
	}

	@Test
	public void prayerStateChangeHasHighConfidence()
	{
		TickAction action = classifier.prayerFromStateChange(2, 1);
		assertEquals(ActionType.PRAYER, action.getType());
		assertEquals(95, action.getConfidence());
	}

	@Test
	public void prayerStateChangeUsesSpecificSprite()
	{
		TickAction action = classifier.prayerFromStateChange(net.runelite.api.Prayer.PROTECT_FROM_MELEE, true, 0);
		assertEquals(ActionType.PRAYER, action.getType());
		assertTrue(action.hasSpriteId());
		assertEquals("Protect", action.getLabel());
	}

	@Test
	public void menuPrayerResolvesNamedSpriteImmediately()
	{
		TickAction action = classifier.classifyMenu(
			MenuAction.CC_OP,
			"Activate",
			"Piety",
			0);
		assertNotNull(action);
		assertEquals(ActionType.PRAYER, action.getType());
		assertEquals("Piety", action.getLabel());
		assertEquals(net.runelite.api.gameval.SpriteID.Prayeron.PIETY, action.getSpriteId());
	}

	@Test
	public void unknownMenuPrayerUsesNeutralOrb()
	{
		TickAction action = classifier.classifyMenu(
			MenuAction.CC_OP,
			"Activate",
			"Some Unknown Prayer Buff",
			0);
		assertNotNull(action);
		assertEquals(ActionType.PRAYER, action.getType());
		assertEquals(PrayerSprites.GENERIC_SPRITE, action.getSpriteId());
	}
}

